// The sandbox, evaluated once per engine before the prelude. QuickJS without an
// embedder's additions reaches nothing: no files, no network, no timers, no
// process. This script fixes the two ambient sources of difference the full
// context brings (the clock, the random numbers) and provides `console`.
// This file is hand-written, as are runtime.js and entry.js; the API modules
// under js/api/ are generated by the test `tests/api_surface.rs` from the
// sources under `flm-ext/src/api/`.
(() => {
  // Date: a fixed instant (the epoch). `new Date()`, `Date.now()` and `Date()`
  // answer it; `new Date(x)` and the parsing and formatting methods are
  // unchanged. A proxy over the real `Date` (not a subclass, whose prototype
  // chain would lead back to the real constructor); the real `Date.now` and
  // `Date.prototype.constructor` are replaced too, so no path reaches the clock.
  const FIXED_MS = 0;
  const RealDate = globalThis.Date;
  const Date = new Proxy(RealDate, {
    construct: (target, args, newTarget) =>
      Reflect.construct(target, args.length ? args : [FIXED_MS], newTarget),
    apply: () => new RealDate(FIXED_MS).toString(),
  });
  RealDate.now = () => FIXED_MS;
  RealDate.prototype.constructor = Date;
  globalThis.Date = Date; // `Date.parse` and `Date.UTC` pass through the proxy

  // Math.random: a fixed sequence (xorshift32), restarted by every handler call.
  const SEED = 0x2545f491;
  let seed = SEED;
  Math.random = () => {
    seed ^= seed << 13;
    seed ^= seed >>> 17;
    seed ^= seed << 5;
    return (seed >>> 0) / 4294967296;
  };
  globalThis.__flm_begin_call = () => { seed = SEED; };

  // performance: a clock the full context adds, whose `now` cannot be
  // replaced; the object is replaced by one whose clock is fixed too.
  if (globalThis.performance) {
    globalThis.performance = Object.freeze({ now: () => 0, timeOrigin: 0 });
  }

  // console: every level to the host's sink, the arguments stringified and joined.
  const flm = globalThis.__flm;
  const to_sink = level => (...args) =>
    flm.console(level, args.map(a => typeof a === "string" ? a : String(a)).join(" "));
  globalThis.console = Object.freeze({
    log: to_sink("log"),
    info: to_sink("info"),
    debug: to_sink("debug"),
    warn: to_sink("warn"),
    error: to_sink("error"),
  });
})();
